<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MAXN = 25;
const int INF = 10007;
const int MAXT = 65;
const int MAXC = 12;

int n, k;
string gridA[MAXN], gridB[MAXN];
int distToExit[MAXN][MAXN];
int memo[MAXT][MAXC][MAXC][MAXC][MAXC];
int dx[4] = {1, 0, -1, 0};
int dy[4] = {0, 1, 0, -1};
vector<pair<int,int>> startList, targetList;

using Flow = int;

struct Edge {
    int from, to;
    Flow cap, flow;
    Edge(int from, int to, Flow cap, Flow flow = 0) : from(from), to(to), cap(cap), flow(flow) {}
};

struct PushRelabel {
    int N;
    vector<Edge> edges;
    vector<vector<int>> adj;
    vector<int> height, inQueue, count;
    vector<Flow> excess;
    queue<int> Q;

    PushRelabel(int N) : N(N), count(N << 1), adj(N), height(N), inQueue(N), excess(N) {}

    int addEdge(int u, int v, int cap) {
        adj[u].push_back((int)edges.size());
        edges.emplace_back(u, v, cap);
        adj[v].push_back((int)edges.size());
        edges.emplace_back(v, u, 0);
        return adj[u].back();
    }

    void enqueue(int u) {
        if (!inQueue[u] && excess[u] > 0) {
            Q.push(u);
            inQueue[u] = true;
        }
    }

    void push(int idx) {
        Edge &e = edges[idx];
        int d = min(e.cap - e.flow, excess[e.from]);
        if (d > 0 && height[e.from] > height[e.to]) {
            e.flow += d;
            excess[e.to] += d;
            excess[e.from] -= d;
            edges[idx ^ 1].flow -= d;
            enqueue(e.to);
        }
    }

    void relabel(int u) {
        count[height[u]]--;
        height[u] = 2 * N - 2;
        for (int i = 0; i < (int)adj[u].size(); ++i) {
            Edge &e = edges[adj[u][i]];
            if (e.cap > e.flow) height[u] = min(height[u], height[e.to]);
        }
        count[++height[u]]++;
    }

    void gapRelabel(int h) {
        for (int u = 0; u < N; ++u) {
            if (height[u] >= h && height[u] < N) {
                count[height[u]]--;
                height[u] = N;
                count[N]++;
                enqueue(u);
            }
        }
    }

    void discharge(int u) {
        for (int i = 0; excess[u] > 0 && i < (int)adj[u].size(); ++i)
            push(adj[u][i]);
        if (excess[u] > 0) {
            if (height[u] < N && count[height[u]] < 2) gapRelabel(height[u]);
            else relabel(u);
        } else if (!Q.empty()) {
            Q.pop();
            inQueue[u] = false;
        }
    }

    Flow getFlow(int src, int snk) {
        height[src] = N;
        inQueue[src] = inQueue[snk] = true;
        count[0] = N - (count[N] = 1);
        for (int i = 0; i < (int)adj[src].size(); ++i) {
            excess[src] += edges[adj[src][i]].cap;
            push(adj[src][i]);
        }
        while (!Q.empty()) discharge(Q.front());
        return excess[snk];
    }
};

void bfsFromZ(int sx, int sy) {
    memset(distToExit, -1, sizeof distToExit);
    queue<pair<int,int>> q;
    distToExit[sx][sy] = 0;
    q.push({sx, sy});
    while (!q.empty()) {
        auto [x, y] = q.front();
        q.pop();
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d];
            int ny = y + dy[d];
            if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
            if (distToExit[nx][ny] != -1) continue;
            if (gridB[nx][ny] == 'Y' || gridB[nx][ny] == 'Z') continue;
            distToExit[nx][ny] = distToExit[x][y] + 1;
            q.push({nx, ny});
        }
    }
}

int canReach(int time, int x0, int y0, int x, int y) {
    if (distToExit[x0][y0] < time) return 0;
    if (x0 == x && y0 == y) return 1;
    if (time >= k) return 0;
    if (distToExit[x0][y0] <= time) return 0;
    int &res = memo[time][x0][y0][x][y];
    if (res != -1) return res;
    for (int d = 0; d < 4; ++d) {
        int nx = x0 + dx[d];
        int ny = y0 + dy[d];
        if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
        if (gridA[nx][ny] == 'Y' || gridA[nx][ny] == 'Z') continue;
        if (canReach(time + 1, nx, ny, x, y)) return res = 1;
    }
    return res = 0;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    memset(memo, -1, sizeof memo);
    cin >> n >> k;
    for (int i = 0; i < n; ++i) cin >> gridA[i];
    for (int i = 0; i < n; ++i) cin >> gridB[i];

    int zx = -1, zy = -1;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (gridB[i][j] == 'Z') zx = i, zy = j;

    bfsFromZ(zx, zy);

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (distToExit[i][j] == -1) distToExit[i][j] = INF;

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            char c = gridA[i][j];
            if (c != 'Z' && c != 'Y' && c != '0') startList.push_back({i, j});
        }

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            char c = gridB[i][j];
            if (c != 'Z' && c != 'Y' && c != '0') targetList.push_back({i, j});
        }

    int S = 0;
    int T = (int)startList.size() + (int)targetList.size() + 1;
    PushRelabel mf(T + 1);

    for (int i = 0; i < (int)startList.size(); ++i)
        mf.addEdge(S, i + 1, gridA[startList[i].first][startList[i].second] - '0');

    for (int i = 0; i < (int)targetList.size(); ++i)
        mf.addEdge((int)startList.size() + i + 1, T,
                   gridB[targetList[i].first][targetList[i].second] - '0');

    for (int i = 0; i < (int)startList.size(); ++i)
        for (int j = 0; j < (int)targetList.size(); ++j)
            if (canReach(0, startList[i].first, startList[i].second,
                         targetList[j].first, targetList[j].second))
                mf.addEdge(i + 1, (int)startList.size() + j + 1, INF);

    cout << mf.getFlow(S, T) << '\n';
    return 0;
}
